} as const;
function ReleaseContent({ onClose }: {
    onClose: () => void;
}) {
    const reduce = useReducedMotion();
    const buttonPress = reduce ? {} : press;
    const fadeVariants: Variants = { enter: { opacity: 0 }, shown: { opacity: 1, x: 0, filter: "blur(0px)", transition: { duration: 0.2, ease: "easeOut" } }, exit: { opacity: 0, transition: { duration: 0.15, ease: "easeOut" } } };
    const reducedLabel = { initial: { opacity: 0 }, animate: { opacity: 1, transition: buttonLabel.animate.transition }, exit: buttonLabel.exit };
    const label = reduce ? reducedLabel : buttonLabel;
    const [index, setIndex] = useState(0);
