        const now = Date.now();
        setInterruptedForward(clamped > index && previousMoveAt.current !== null && now - previousMoveAt.current < 100 && window.innerWidth <= 767);
        previousMoveAt.current = now;
        setDirection(clamped > index ? 1 : -1);
        setIndex(clamped);
    }, [index]);
    const slide = slides[index];
    return (<div className="art:p-2" onKeyDown={(event) => {
