                go(index - 1);
            if (reduce)
                dragX.set(0);
            else
                animate(dragX, 0, ARTEMIS_SPRING_PANEL);
        }} onPointerCancel={() => { gesture.current = null; if (reduce)
        dragX.set(0);
    else
        animate(dragX, 0, ARTEMIS_SPRING_PANEL); }}>
          <AnimatePresence initial={false} custom={{ direction, interruptedForward }}>
