            </motion.div>
          </AnimatePresence>
        </div>
        <p aria-live="polite" className="art:sr-only">{`Slide ${index + 1} of ${slides.length}`}</p>
        <div className="art:mt-5">
          <div className="art:flex art:flex-col art:gap-2 art:sm:flex-row art:sm:items-center art:sm:justify-between">
            <div className="art:flex art:justify-center art:sm:justify-start"><div className="art:flex art:items-center">
